1	import { useState, useEffect } from "react";
2	import { useParams, useNavigate, Link } from "react-router-dom";
3	import { useQuery } from "@tanstack/react-query";
4	import { supabase } from "@/integrations/supabase/client";
5	import { Skeleton } from "@/components/ui/skeleton";
6	import { Badge } from "@/components/ui/badge";
7	import { Button } from "@/components/ui/button";
8	import { Input } from "@/components/ui/input";
9	import { Briefcase, Layers, Search, Globe, Linkedin, Twitter, Instagram, Facebook, Bell } from "lucide-react";
10	import JobListingCard from "@/components/career/JobListingCard";
11	import { toast } from "sonner";
12	
13	interface Benefit {
14	  icon: string;
15	  title: string;
16	  description: string;
17	}
18	
19	interface SocialLinks {
20	  website?: string;
21	  linkedin?: string;
22	  twitter?: string;
23	  instagram?: string;
24	  facebook?: string;
25	}
26	
27	interface CareerConfig {
28	  company_name: string;
29	  logo_url: string | null;
30	  brand_color: string;
31	  tagline: string | null;
32	  about: string | null;
33	  // Enhanced branding
34	  custom_css: string | null;
35	  cover_image_url: string | null;
36	  // Culture
37	  culture_title: string | null;
38	  culture_description: string | null;
39	  benefits: Benefit[] | null;
40	  // Social
41	  social_links: SocialLinks | null;
42	  // SEO
43	  meta_description: string | null;
44	  meta_keywords: string | null;
45	}
46	
47	interface CareerJob {
48	  id: string;
49	  title: string;
50	  job_description?: string | null;
51	  location: string | null;
52	  department: string | null;
53	  employment_type: string | null;
54	  salary_range: string | null;
55	  created_at: string;
56	  expires_at: string | null;
57	  is_featured: boolean | null;
58	}
59	
60	// ---------------------------------------------------------------------------
61	// Helpers
62	// ---------------------------------------------------------------------------
63	
64	const iconFallbacks: Record<string, string> = {
65	  Heart: "❤️", Star: "⭐", Zap: "⚡", Globe: "🌍", Shield: "🛡️",
66	  Award: "🏆", Coffee: "☕", Users: "👥", TrendingUp: "📈", Home: "🏠",
67	  Smile: "😊", Clock: "⏰", DollarSign: "💰", Gift: "🎁", Briefcase: "💼",
68	  Laptop: "💻", Plane: "✈️", BookOpen: "📚", Music: "🎵", Camera: "📷",
69	};
70	
71	function BenefitIcon({ name }: { name: string }) {
72	  const emoji = iconFallbacks[name] ?? "✦";
73	  return (
74	    <span className="text-2xl leading-none" role="img" aria-label={name}>
75	      {emoji}
76	    </span>
77	  );
78	}
79	
80	// ---------------------------------------------------------------------------
81	// Subscribe form
82	// ---------------------------------------------------------------------------
83	
84	function SubscribeSection({ teamId, brandColor }: { teamId: string; brandColor: string }) {
85	  const [email, setEmail] = useState("");
86	  const [submitting, setSubmitting] = useState(false);
87	  const [subscribed, setSubscribed] = useState(false);
88	
89	  const handleSubscribe = async (e: React.FormEvent) => {
90	    e.preventDefault();
91	    if (!email.trim() || !teamId) return;
92	    setSubmitting(true);
93	    try {
94	      const { error } = await (supabase as any)
95	        .from("career_subscribers")
96	        .insert({ team_id: teamId, email: email.trim().toLowerCase() });
97	      if (error) {
98	        if (error.code === "23505") {
99	          toast.info("You're already subscribed to job alerts.");
100	        } else {
101	          throw error;
102	        }
103	      } else {
104	        setSubscribed(true);
105	        toast.success("Subscribed! We'll notify you about new positions.");
106	      }
107	    } catch (err: unknown) {
108	      const msg = err instanceof Error ? err.message : "Failed to subscribe";
109	      toast.error(msg);
110	    } finally {
111	      setSubmitting(false);
112	    }
113	  };
114	
115	  if (subscribed) {
116	    return (
117	      <section className="py-12 border-t border-border bg-muted/30">
118	        <div className="max-w-md mx-auto text-center px-4 space-y-2">
119	          <Bell className="h-8 w-8 mx-auto text-primary" />
120	          <h3 className="text-base font-semibold">You&apos;re subscribed</h3>
121	          <p className="text-sm text-muted-foreground">
122	            We&apos;ll email you when new positions are posted.
123	          </p>
124	        </div>
125	      </section>
126	    );
127	  }
128	
129	  return (
130	    <section className="py-12 border-t border-border bg-muted/30">
131	      <div className="max-w-md mx-auto text-center px-4">
132	        <Bell className="h-7 w-7 mx-auto text-muted-foreground mb-3" />
133	        <h3 className="text-lg font-semibold mb-2">Get notified about new positions</h3>
134	        <p className="text-sm text-muted-foreground mb-4">
135	          Enter your email and we&apos;ll send you updates when new jobs are posted.
136	        </p>
137	        <form className="flex gap-2" onSubmit={handleSubscribe}>
138	          <Input
139	            type="email"
140	            placeholder="your@email.com"
141	            required
142	            value={email}
143	            onChange={(e) => setEmail(e.target.value)}
144	            disabled={submitting}
145	            className="flex-1"
146	          />
147	          <Button
148	            type="submit"
149	            disabled={submitting || !email.trim()}
150	            style={{ backgroundColor: brandColor }}
151	            className="text-white hover:opacity-90 shrink-0"
152	          >
153	            {submitting ? "Subscribing…" : "Subscribe"}
154	          </Button>
155	        </form>
156	      </div>
157	    </section>
158	  );
159	}
160	
161	export default function CareerPage() {
162	  const { slug } = useParams<{ slug: string }>();
163	  const navigate = useNavigate();
164	  const [selectedDept, setSelectedDept] = useState<string | null>(null);
165	  const [selectedLocation, setSelectedLocation] = useState<string | null>(null);
166	  const [searchQuery, setSearchQuery] = useState("");
167	
168	  const { data, isLoading } = useQuery({
169	    queryKey: ["career-page", slug],
170	    queryFn: async () => {
171	      if (!slug) return null;
172	      const { data, error } = await supabase.rpc("get_career_page", {
173	        p_slug: slug,
174	      });
175	      if (error) throw error;
176	      return data as unknown as { config: CareerConfig; jobs: CareerJob[]; team_id?: string } | null;
177	    },
178	    enabled: !!slug,
179	    staleTime: 60_000,
180	  });
181	
182	  const config = data?.config;
183	  const teamId: string = (data as any)?.team_id ?? "";
184	  const jobs = data?.jobs ?? [];
185	  const brandColor = config?.brand_color ?? "#6366f1";
186	  const benefits = Array.isArray(config?.benefits) ? (config!.benefits as Benefit[]) : [];
187	  const socialLinks = ((config?.social_links ?? {}) as SocialLinks);
188	  const hasSocialLinks = Object.values(socialLinks).some(Boolean);
189	
190	  const departments = [
191	    ...new Set(jobs.map((j) => j.department).filter(Boolean)),
192	  ] as string[];
193	  const locations = [
194	    ...new Set(jobs.map((j) => j.location).filter(Boolean)),
195	  ] as string[];
196	
197	  const filteredJobs = jobs.filter((j) => {
198	    if (selectedDept && j.department !== selectedDept) return false;
199	    if (selectedLocation && j.location !== selectedLocation) return false;
200	    if (searchQuery.trim()) {
201	      const q = searchQuery.toLowerCase();
202	      const match =
203	        (j.title ?? "").toLowerCase().includes(q) ||
204	        (j.department ?? "").toLowerCase().includes(q) ||
205	        (j.location ?? "").toLowerCase().includes(q);
206	      if (!match) return false;
207	    }
208	    return true;
209	  });
210	
211	  // Featured first, then regular
212	  const featuredJobs = filteredJobs.filter((j) => j.is_featured);
213	  const regularJobs = filteredJobs.filter((j) => !j.is_featured);
214	
215	  // SEO meta tags
216	  useEffect(() => {
217	    if (!config) return;
218	    document.title = `Careers at ${config.company_name} | Rankora`;
219	
220	    const setMeta = (nameOrProp: string, content: string) => {
221	      const isOg = nameOrProp.startsWith("og:");
222	      const attr = isOg ? "property" : "name";
223	      let el =
224	        document.querySelector(`meta[property="${nameOrProp}"]`) ||
225	        document.querySelector(`meta[name="${nameOrProp}"]`);
226	      if (!el) {
227	        el = document.createElement("meta");
228	        el.setAttribute(attr, nameOrProp);
229	        document.head.appendChild(el);
230	      }
231	      el.setAttribute("content", content);
232	    };
233	
234	    const desc = config.meta_description ?? config.tagline ?? `View open positions at ${config.company_name}`;
235	    setMeta("description", desc);
236	    if (config.meta_keywords) setMeta("keywords", config.meta_keywords);
237	    setMeta("og:title", `Careers at ${config.company_name}`);
238	    setMeta("og:description", desc);
239	    setMeta("og:type", "website");
240	    setMeta("og:url", window.location.href);
241	    if (config.logo_url) setMeta("og:image", config.logo_url);
242	
243	    return () => {
244	      document.title = "Rankora";
245	      ["description", "keywords", "og:title", "og:description", "og:type", "og:url", "og:image"].forEach(
246	        (key) => {
247	          document.querySelector(`meta[property="${key}"]`)?.remove();
248	          document.querySelector(`meta[name="${key}"]`)?.remove();
249	        }
250	      );
251	    };
252	  }, [config]);
253	
254	  // JSON-LD — JobPosting ItemList for all published jobs
255	  useEffect(() => {
256	    if (!jobs.length || !config) return;
257	
258	    const jsonLd = {
259	      "@context": "https://schema.org",
260	      "@type": "ItemList",
261	      itemListElement: jobs.map((job, i) => ({
262	        "@type": "ListItem",
263	        position: i + 1,
264	        item: {
265	          "@type": "JobPosting",
266	          title: job.title,
267	          description: job.job_description
268	            ? job.job_description.slice(0, 500)
269	            : job.title,
270	          datePosted: job.created_at,
271	          directApply: true,
272	          ...(job.employment_type
273	            ? {
274	                employmentType: job.employment_type
275	                  .toUpperCase()
276	                  .replace(/-/g, "_"),
277	              }
278	            : {}),
279	          ...(job.location
280	            ? {
281	                jobLocation: {
282	                  "@type": "Place",
283	                  address: {
284	                    "@type": "PostalAddress",
285	                    addressLocality: job.location,
286	                  },
287	                },
288	              }
289	            : {}),
290	          hiringOrganization: {
291	            "@type": "Organization",
292	            name: config.company_name,
293	            ...(config.logo_url ? { logo: config.logo_url } : {}),
294	          },
295	        },
296	      })),
297	    };
298	
299	    let script = document.getElementById(
300	      "career-jsonld"
301	    ) as HTMLScriptElement | null;
302	    if (!script) {
303	      script = document.createElement("script");
304	      script.id = "career-jsonld";
305	      script.setAttribute("type", "application/ld+json");
306	      document.head.appendChild(script);
307	    }
308	    script.textContent = JSON.stringify(jsonLd);
309	
310	    return () => {
311	      document.getElementById("career-jsonld")?.remove();
312	    };
313	  }, [jobs, config]);
314	
315	  const handleApply = (jobId: string) => navigate(`/apply/${jobId}`);
316	
317	  // Loading
318	  if (isLoading) {
319	    return (
320	      <div className="min-h-screen bg-background flex flex-col">
321	        <header className="border-b border-border">
322	          <div className="max-w-4xl mx-auto px-4 py-4 flex items-center gap-3">
323	            <Skeleton className="h-8 w-8 rounded" />
324	            <Skeleton className="h-5 w-32" />
325	          </div>
326	        </header>
327	        <div className="max-w-4xl mx-auto px-4 py-12 w-full space-y-4">
328	          <Skeleton className="h-8 w-64 mx-auto" />
329	          <Skeleton className="h-4 w-48 mx-auto" />
330	          <div className="space-y-4 mt-8">
331	            {[1, 2, 3].map((i) => (
332	              <Skeleton key={i} className="h-24 w-full rounded-xl" />
333	            ))}
334	          </div>
335	        </div>
336	      </div>
337	    );
338	  }
339	
340	  // Not found
341	  if (!config) {
342	    return (
343	      <div className="min-h-screen bg-background flex flex-col">
344	        <header className="border-b border-border">
345	          <div className="max-w-4xl mx-auto px-4 py-4">
346	            <Link
347	              to="/"
348	              className="flex items-center gap-2 text-sm font-semibold"
349	            >
350	              <Layers className="h-5 w-5 text-primary" /> Rankora
351	            </Link>
352	          </div>
353	        </header>
354	        <main className="flex-1 flex items-center justify-center px-4 py-16">
355	          <div className="text-center space-y-4">
356	            <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center mx-auto">
357	              <Briefcase className="h-7 w-7 text-muted-foreground" />
358	            </div>
359	            <h1 className="text-xl font-semibold">Career page not found</h1>
360	            <p className="text-sm text-muted-foreground">
361	              This career page may have been removed or is not yet active.
362	            </p>
363	            <Link
364	              to="/"
365	              className="text-sm font-medium text-primary hover:text-primary/80 transition-colors"
366	            >
367	              Back to Rankora
368	            </Link>
369	          </div>
370	        </main>
371	      </div>
372	    );
373	  }
374	
375	  // Active career page
376	  return (
377	    <div className="min-h-screen bg-background flex flex-col">
378	      {/* Custom CSS injection */}
379	      {config.custom_css && (
380	        <style dangerouslySetInnerHTML={{ __html: config.custom_css }} />
381	      )}
382	
383	      {/* Header */}
384	      <header className="sticky top-0 z-10 bg-background/95 backdrop-blur border-b border-border">
385	        <div className="max-w-4xl mx-auto px-4 py-4 flex items-center gap-3">
386	          {config.logo_url && (
387	            <img
388	              src={config.logo_url}
389	              alt={config.company_name}
390	              className="h-8 w-8 rounded object-cover"
391	            />
392	          )}
393	          <span className="font-semibold text-lg text-foreground">
394	            {config.company_name}
395	          </span>
396	        </div>
397	      </header>
398	
399	      {/* Cover image */}
400	      {config.cover_image_url && (
401	        <div
402	          className="w-full h-48 sm:h-64 bg-cover bg-center"
403	          style={{ backgroundImage: `url(${config.cover_image_url})` }}
404	          role="img"
405	          aria-label={`${config.company_name} cover image`}
406	        />
407	      )}
408	
409	      {/* Hero */}
410	      <div className="py-12 px-4" style={{ backgroundColor: brandColor + "0D" }}>
411	        <div className="max-w-4xl mx-auto text-center space-y-3">
412	          <h1 className="text-3xl font-bold text-foreground">
413	            {config.company_name}
414	          </h1>
415	          {config.tagline && (
416	            <p className="text-lg text-muted-foreground">{config.tagline}</p>
417	          )}
418	          {config.about && (
419	            <p className="text-sm text-muted-foreground max-w-2xl mx-auto leading-relaxed mt-2">
420	              {config.about}
421	            </p>
422	          )}
423	          <Badge
424	            variant="secondary"
425	            className="mt-4 text-sm"
426	            style={{ borderColor: brandColor + "40" }}
427	          >
428	            {jobs.length} Open Position{jobs.length !== 1 ? "s" : ""}
429	          </Badge>
430	        </div>
431	      </div>
432	
433	      {/* Search + Filters */}
434	      {jobs.length > 0 && (
435	        <div className="max-w-4xl mx-auto px-4 pt-6 space-y-3">
436	          {/* Search bar */}
437	          <div className="relative">
438	            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
439	            <Input
440	              placeholder="Search positions..."
441	              value={searchQuery}
442	              onChange={(e) => setSearchQuery(e.target.value)}
443	              className="pl-9 h-10 bg-background"
444	            />
445	          </div>
446	
447	          {/* Filter pills */}
448	          <div className="flex gap-4 flex-wrap">
449	            {/* Department filter */}
450	            {departments.length > 1 && (
451	              <div className="flex gap-1.5 flex-wrap">
452	                <button
453	                  onClick={() => setSelectedDept(null)}
454	                  className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
455	                    !selectedDept ? "text-white" : "bg-muted text-muted-foreground hover:bg-muted/80"
456	                  }`}
457	                  style={!selectedDept ? { backgroundColor: brandColor } : undefined}
458	                >
459	                  All Depts
460	                </button>
461	                {departments.map((dept) => (
462	                  <button
463	                    key={dept}
464	                    onClick={() => setSelectedDept(dept)}
465	                    className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
466	                      selectedDept === dept ? "text-white" : "bg-muted text-muted-foreground hover:bg-muted/80"
467	                    }`}
468	                    style={selectedDept === dept ? { backgroundColor: brandColor } : undefined}
469	                  >
470	                    {dept}
471	                  </button>
472	                ))}
473	              </div>
474	            )}
475	
476	            {/* Location filter */}
477	            {locations.length > 1 && (
478	              <div className="flex gap-1.5 flex-wrap">
479	                <button
480	                  onClick={() => setSelectedLocation(null)}
481	                  className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
482	                    !selectedLocation ? "text-white" : "bg-muted text-muted-foreground hover:bg-muted/80"
483	                  }`}
484	                  style={!selectedLocation ? { backgroundColor: brandColor } : undefined}
485	                >
486	                  All Locations
487	                </button>
488	                {locations.map((loc) => (
489	                  <button
490	                    key={loc}
491	                    onClick={() => setSelectedLocation(loc)}
492	                    className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
493	                      selectedLocation === loc ? "text-white" : "bg-muted text-muted-foreground hover:bg-muted/80"
494	                    }`}
495	                    style={selectedLocation === loc ? { backgroundColor: brandColor } : undefined}
496	                  >
497	                    {loc}
498	                  </button>
499	                ))}
500	              </div>
501	            )}
502	          </div>
503	
504	          {/* Result count */}
505	          {(searchQuery || selectedDept || selectedLocation) && (
506	            <p className="text-xs text-muted-foreground">
507	              {filteredJobs.length} position{filteredJobs.length !== 1 ? "s" : ""} found
508	            </p>
509	          )}
510	        </div>
511	      )}
512	
513	      {/* Job listings */}
514	      <main className="flex-1 max-w-4xl mx-auto px-4 py-6 w-full">
515	        {filteredJobs.length === 0 ? (
516	          <div className="text-center py-16 space-y-3">
517	            <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center mx-auto">
518	              <Briefcase className="h-7 w-7 text-muted-foreground/40" />
519	            </div>
520	            <h2 className="text-base font-medium text-foreground">
521	              No open positions right now
522	            </h2>
523	            <p className="text-sm text-muted-foreground">
524	              Check back soon for new opportunities.
525	            </p>
526	          </div>
527	        ) : (
528	          <div className="space-y-6">
529	            {/* Featured jobs */}
530	            {featuredJobs.length > 0 && (
531	              <div className="space-y-3">
532	                <h2 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
533	                  Featured Positions
534	                </h2>
535	                <div className="grid gap-4">
536	                  {featuredJobs.map((job) => (
537	                    <JobListingCard
538	                      key={job.id}
539	                      id={job.id}
540	                      title={job.title}
541	                      location={job.location}
542	                      department={job.department}
543	                      employmentType={job.employment_type}
544	                      salaryRange={job.salary_range}
545	                      createdAt={job.created_at}
546	                      brandColor={brandColor}
547	                      onApply={handleApply}
548	                      detailUrl={slug ? `/careers/${slug}/jobs/${job.id}` : undefined}
549	                      expiresAt={job.expires_at}
550	                      isFeatured={true}
551	                    />
552	                  ))}
553	                </div>
554	              </div>
555	            )}
556	
557	            {/* Regular jobs */}
558	            {regularJobs.length > 0 && (
559	              <div className="space-y-3">
560	                {featuredJobs.length > 0 && (
561	                  <h2 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
562	                    All Positions
563	                  </h2>
564	                )}
565	                <div className="grid gap-4">
566	                  {regularJobs.map((job) => (
567	                    <JobListingCard
568	                      key={job.id}
569	                      id={job.id}
570	                      title={job.title}
571	                      location={job.location}
572	                      department={job.department}
573	                      employmentType={job.employment_type}
574	                      salaryRange={job.salary_range}
575	                      createdAt={job.created_at}
576	                      brandColor={brandColor}
577	                      onApply={handleApply}
578	                      detailUrl={slug ? `/careers/${slug}/jobs/${job.id}` : undefined}
579	                      expiresAt={job.expires_at}
580	                      isFeatured={false}
581	                    />
582	                  ))}
583	                </div>
584	              </div>
585	            )}
586	          </div>
587	        )}
588	      </main>
589	
590	      {/* Culture & Benefits section */}
591	      {config.culture_description && (
592	        <section className="py-16 border-t border-border">
593	          <div className="max-w-4xl mx-auto px-4">
594	            <div className="text-center space-y-3 mb-10">
595	              <h2 className="text-2xl font-bold text-foreground">
596	                {config.culture_title || "Why Join Us"}
597	              </h2>
598	              <p className="text-muted-foreground max-w-2xl mx-auto leading-relaxed">
599	                {config.culture_description}
600	              </p>
601	            </div>
602	            {benefits.length > 0 && (
603	              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
604	                {benefits.map((benefit, i) => (
