<TabsContent value="testimonials" className="mt-6 space-y-6">
  <Card className="border border-border/60 shadow-sm">
    <CardHeader className="pb-3">
      <div className="flex items-center justify-between">
        <div>
          <CardTitle className="text-sm font-semibold flex items-center gap-2">
            <Quote className="h-4 w-4 text-primary" />
            Team Testimonials
          </CardTitle>
          <CardDescription className="text-xs mt-1">
            Add quotes from your team. Shown on the career page below the culture section. Max 6.
          </CardDescription>
        </div>
        <Badge variant="outline" className="text-xs shrink-0">
          {testimonials.length}/6
        </Badge>
      </div>
    </CardHeader>
    <CardContent className="space-y-5">
      {/* Existing testimonials */}
      {testimonials.length === 0 ? (
        <div className="rounded-lg border border-dashed border-border p-8 text-center">
          <Quote className="h-8 w-8 text-muted-foreground/30 mx-auto mb-2" />
          <p className="text-xs text-muted-foreground">
            No testimonials yet. Add one below.
          </p>
        </div>
      ) : (
        <div className="space-y-3">
          {testimonials.map((t, index) => (
            <div
              key={index}
              className="rounded-xl border border-border bg-muted/20 p-4 space-y-2"
            >
              <div className="flex items-start justify-between gap-3">
                <p className="text-sm text-foreground italic leading-relaxed flex-1">
                  &ldquo;{t.quote}&rdquo;
                </p>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="h-7 w-7 text-muted-foreground hover:text-destructive shrink-0"
                  onClick={() =>
                    setTestimonials((prev) => prev.filter((_, i) => i !== index))
                  }
                  disabled={isSaving}
                  aria-label={`Remove testimonial from ${t.name}`}
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </Button>
              </div>
              <div className="flex items-center gap-2">
                <p className="text-xs font-semibold text-foreground">{t.name}</p>
                {t.role && (
                  <span className="text-xs text-muted-foreground">— {t.role}</span>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Add new testimonial form */}
      {testimonials.length < 6 && (
        <div className="rounded-xl border border-border/60 bg-background p-4 space-y-3">
          <p className="text-xs font-semibold text-foreground">Add testimonial</p>
          <div className="space-y-2">
            <div className="space-y-1">
              <Label className="text-xs">Quote</Label>
              <Textarea
                placeholder="Working here has been an incredible journey…"
                value={newTestimonialQuote}
                onChange={(e) => setNewTestimonialQuote(e.target.value)}
                disabled={isSaving}
                rows={3}
                className="resize-none text-sm"
                maxLength={500}
              />
              <p className="text-xs text-muted-foreground text-right">
                {newTestimonialQuote.length}/500
              </p>
            </div>
            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <Label className="text-xs">Name</Label>
                <Input
                  placeholder="Jane Smith"
                  value={newTestimonialName}
                  onChange={(e) => setNewTestimonialName(e.target.value)}
                  disabled={isSaving}
                  className="h-8 text-sm"
                  maxLength={80}
                />
              </div>
              <div className="space-y-1">
                <Label className="text-xs">Role</Label>
                <Input
                  placeholder="Senior Engineer"
                  value={newTestimonialRole}
                  onChange={(e) => setNewTestimonialRole(e.target.value)}
                  disabled={isSaving}
                  className="h-8 text-sm"
                  maxLength={80}
                />
              </div>
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Photo URL (optional)</Label>
              <Input
                placeholder="https://example.com/photo.jpg"
                value={newTestimonialPhoto}
                onChange={(e) => setNewTestimonialPhoto(e.target.value)}
                disabled={isSaving}
                type="url"
                className="h-8 text-sm"
              />
            </div>
          </div>
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="gap-1.5 h-8"
            disabled={isSaving || !newTestimonialQuote.trim() || !newTestimonialName.trim()}
            onClick={() => {
              if (!newTestimonialQuote.trim() || !newTestimonialName.trim()) return;
              setTestimonials((prev) => [
                ...prev,
                {
                  quote: newTestimonialQuote.trim(),
                  name: newTestimonialName.trim(),
                  role: newTestimonialRole.trim(),
                  photo_url: newTestimonialPhoto.trim() || undefined,
                },
              ]);
              setNewTestimonialQuote("");
              setNewTestimonialName("");
              setNewTestimonialRole("");
              setNewTestimonialPhoto("");
            }}
          >
            <Plus className="h-3.5 w-3.5" />
            Add testimonial
          </Button>
        </div>
      )}

      <div className="flex justify-end">
        <SaveButton isSaving={isSaving} onClick={handleSave} />
      </div>
    </CardContent>
  </Card>
</TabsContent>

{/* ---------------------------------------------------------------- */}
{/* Tab 4: Social & SEO                                               */}
{/* ---------------------------------------------------------------- */}

